/*
 * dgVoodoo's actual lanczos-3 presentation PS seen bound at the verified
 * mapper Draw. The DXBC-integrity header, full-container FNV-1a, and tail are
 * all required so a version drift fails closed rather than targeting a shader
 * based only on size or object order.
 */
static const unsigned char mapper_problem_shader_header[32u] = {
    0x44, 0x58, 0x42, 0x43, 0x84, 0xD9, 0x68, 0xE9,
    0x37, 0x47, 0xF5, 0xB7, 0xE2, 0xCE, 0x35, 0x36,
    0x98, 0xEC, 0xFE, 0xA1, 0x01, 0x00, 0x00, 0x00,
    0x74, 0x10, 0x00, 0x00, 0x03, 0x00, 0x00, 0x00
};
static const unsigned char mapper_problem_shader_tail[32u] = {
    0x46, 0x02, 0x10, 0x00, 0x01, 0x00, 0x00, 0x00,
    0x36, 0x00, 0x00, 0x05, 0x82, 0x20, 0x10, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x01, 0x40, 0x00, 0x00,
    0x00, 0x00, 0x80, 0x3F, 0x3E, 0x00, 0x00, 0x01
};

static unsigned long mapper_shader_fnv1a32(const unsigned char *bytes,
                                           size_t size) {
    unsigned long value = 2166136261u;
    size_t index;
    for (index = 0u; index < size; ++index) {
        value ^= bytes[index];
        value *= 16777619u;
    }
    return value;
}

