int mtw_mapper_callsite_supported(const unsigned char *bytes, size_t size) {
    return bytes != NULL && size == MTW_MAPPER_CALLSITE_SIZE &&
           memcmp(bytes, mapper_callsite_expected, MTW_MAPPER_CALLSITE_SIZE) == 0;
}

const unsigned char *mtw_mapper_pixel_shader_bytecode(size_t *size) {
    if (size != NULL) {
        *size = sizeof(mapper_single_sample_linear_bytecode);
    }
    return mapper_single_sample_linear_bytecode;
}

int mtw_mapper_pixel_shader_matches(const void *bytes, size_t size) {
    return bytes != NULL && size == sizeof(mapper_single_sample_linear_bytecode) &&
           memcmp(bytes, mapper_single_sample_linear_bytecode,
                  sizeof(mapper_single_sample_linear_bytecode)) == 0;
}

int mtw_mapper_problem_pixel_shader_matches(const void *bytes, size_t size) {
    const unsigned char *shader = (const unsigned char *)bytes;
    return shader != NULL && size == 4212u &&
           memcmp(shader, mapper_problem_shader_header,
                  sizeof(mapper_problem_shader_header)) == 0 &&
           memcmp(shader + size - sizeof(mapper_problem_shader_tail),
                  mapper_problem_shader_tail,
                  sizeof(mapper_problem_shader_tail)) == 0 &&
           mapper_shader_fnv1a32(shader, size) == 0xE0ED4D3Au;
}
